"""Small offline supervisor view of one verified team result, without new judgment."""
import html
import json


def render(result):
    payload = json.dumps(result, ensure_ascii=False, separators=(',', ':'), allow_nan=False)
    payload = payload.replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    aid = html.escape(result['team_analysis_id'], quote=True)
    template = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src 'none'; connect-src 'none'; base-uri 'none'; form-action 'none'">
<title>销售管理 · 主管视图</title><style>
:root{--ink:#192a3a;--muted:#697785;--line:#e3e8ed;--blue:#275d75;--pale:#edf4f7;--amber:#976518;--red:#a24946}
*{box-sizing:border-box}body{margin:0;background:#f5f7f9;color:var(--ink);font:15px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}button,select,input{font:inherit}button{cursor:pointer}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #82bbd3;outline-offset:3px}aside.sidebar{position:fixed;inset:0 auto 0 0;width:196px;background:#fff;border-right:1px solid var(--line);padding:30px 18px}.brand{font-size:22px;font-weight:750;margin:0 10px 38px}.nav{display:grid;gap:10px}.nav button,.utility button{background:none;border:0;text-align:left;color:var(--muted);padding:12px 14px;border-radius:9px}.nav button.active{background:var(--pale);color:var(--blue);font-weight:700}.utility{position:absolute;bottom:24px;display:grid;gap:5px}.utility button{font-size:13px;padding:6px 14px}main{margin-left:196px;padding:34px 4vw;max-width:1600px}header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:28px}h1{font-size:29px;margin:0;letter-spacing:.02em}h2{font-size:20px;margin:0}h3{font-size:17px;margin:0 0 12px}.muted{color:var(--muted);font-size:13px}.toolbar{display:flex;gap:12px;align-items:center}select,input{border:1px solid var(--line);background:white;border-radius:7px;padding:8px 12px;color:var(--ink)}.section{margin:34px 0}.section-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:17px}.link{border:0;background:none;color:var(--blue);padding:3px;font-weight:600}.metrics,.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.metric,.card,.chart,.topic{background:white;border:1px solid var(--line);border-radius:14px;padding:24px}.metric strong{display:block;font-size:31px;line-height:1.3;margin:10px 0;color:var(--blue)}.metric small{font-size:12px;color:var(--muted)}.track{height:6px;background:#edf1f4;border-radius:6px;overflow:hidden;margin:14px 0 8px}.fill{height:100%;background:var(--blue);border-radius:6px}.tag{display:inline-block;font-size:11px;border-radius:5px;padding:2px 8px;background:var(--pale);color:var(--blue)}.tag.red{background:#faeeee;color:var(--red)}.tag.orange,.tag.yellow{background:#fff4df;color:var(--amber)}.card{display:flex;flex-direction:column;gap:13px;min-height:216px}.card h3{margin:0}.card .question{padding:12px 0 0;border-top:1px solid var(--line);font-size:14px}.card .link{align-self:flex-start;margin-top:auto}.person{color:var(--muted);font-size:12px}.hints{background:#fff;border:1px solid var(--line);border-radius:14px;padding:3px 24px}.hint{display:flex;gap:24px;align-items:center;padding:20px 0}.hint+.hint{border-top:1px solid var(--line)}.hint b{min-width:55px}.hint .link{margin-left:auto}.topic{display:grid;grid-template-columns:1.6fr 1fr;gap:32px}.topic .practice{border-left:1px solid var(--line);padding-left:26px}.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.chip{border:1px solid var(--line);border-radius:6px;background:#fff;color:var(--blue);padding:4px 10px;font-size:12px}.bar-row{margin:20px 0}.bar-label{display:flex;justify-content:space-between;gap:12px;font-size:12px}.chart strong{font-size:24px;color:var(--blue)}.missing{padding:32px 0;color:var(--muted)}footer{font-size:11px;color:var(--muted);margin:28px 0}.detail-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,1fr);gap:26px}.evidence,.detail-block{background:#fff;border:1px solid var(--line);border-radius:12px;padding:23px}.evidence{max-height:74vh;overflow:auto}.message{margin:15px 0 22px;padding:14px 16px;background:#f4f7fa;border-left:3px solid #b7c9d3;border-radius:5px;white-space:pre-wrap;overflow-wrap:anywhere}.message .meta{font-size:11px;color:var(--muted);margin-bottom:7px;white-space:normal}.detail-block{margin-bottom:18px}.detail-block p{margin:8px 0;white-space:pre-wrap;overflow-wrap:anywhere}.detail-block dt{font-size:12px;color:var(--muted);margin-top:14px}.detail-block dd{margin:3px 0}.phases{display:flex;gap:5px;flex-wrap:wrap;margin-top:15px}.empty{color:var(--muted);padding:28px;border:1px dashed var(--line);border-radius:10px}.overlay{position:fixed;inset:0;background:#192a3a55;display:flex;align-items:center;justify-content:center;padding:28px;z-index:10}.modal{background:#fff;max-width:1000px;width:100%;max-height:88vh;overflow:auto;border-radius:16px;padding:28px}.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.close{border:0;border-radius:50%;background:#f1f4f7;font-size:22px;width:35px;height:35px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:13px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-weight:500}.note{padding:14px;background:#f7f9fa;border-radius:7px;color:var(--muted);font-size:12px;white-space:pre-wrap}.nowrap{white-space:nowrap}pre{white-space:pre-wrap;overflow-wrap:anywhere}
@media(max-width:1050px){.grid,.metrics{gap:12px}.card,.metric,.chart{padding:18px}main{padding:26px}.detail-grid{grid-template-columns:1fr}.evidence{max-height:none}}@media(max-width:760px){aside.sidebar{position:static;width:100%;padding:16px;border-right:0;border-bottom:1px solid var(--line)}.brand{display:none}.nav{display:flex}.nav button{flex:1;text-align:center}.utility{position:static;display:flex;justify-content:center;margin-top:8px}.utility button{padding:4px 10px}.metrics,.grid{grid-template-columns:1fr}main{margin:0;padding:22px 16px}header{align-items:flex-start;flex-direction:column}.topic{grid-template-columns:1fr}.topic .practice{border:0;padding:0}.hint{align-items:flex-start;gap:12px}.overlay{padding:12px}.modal{padding:18px}h1{font-size:25px}.toolbar{width:100%;justify-content:space-between}table{min-width:580px}.table-wrap{overflow:auto}}
</style></head><body><aside class="sidebar"><div class="brand">留学辅导销售助手</div><nav class="nav" aria-label="管理页面"><button data-page="overview" class="active">经营总览</button><button data-page="coaching">顾问带教</button></nav><div class="utility"><button data-modal="cases">全部案例</button><button data-modal="decisions">完整决策记录</button><button data-modal="sources">数据与口径</button></div></aside><main data-team-analysis-id="__AID__" id="main"></main><div id="modal-root"></div><script id="team-data" type="application/json">__PAYLOAD__</script><script>
'use strict';
const D=JSON.parse(document.getElementById('team-data').textContent), main=document.getElementById('main'), modalRoot=document.getElementById('modal-root');let page='overview',scope='all',lastPage='overview';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v==null?'待补数据':'¥'+Number(v).toLocaleString('zh-CN',{maximumFractionDigits:2}),pct=v=>v==null?'待核':(Number(v)*100).toFixed(1)+'%',num=v=>v==null?'待核':String(v);
const averageNote=s=>({no_first_formal_purchases:'本期无正式首购',partial_order_coverage:'首单金额覆盖不全，待补齐',missing_order_amounts:'待补完整首次正式订单金额',complete:'仅首次正课订单，不累计续费'}[s?.average_order_status]||'待接入首次正式订单金额');
const rowFor=(sid,cid)=>D.cases.find(r=>r.sales_id===sid&&r.case_id===cid),rowIndex=r=>D.cases.findIndex(c=>c.sales_id===r.sales_id&&c.case_id===r.case_id);
const filtered=arr=>scope==='all'?arr:arr.filter(r=>r.sales_id===scope),names={reception:'承接',diagnosis:'诊断',proposal:'方案报价',objection:'异议处理',close:'成交推进'},states={done:'完成',gap:'不足',not_done:'未完成',not_needed:'无需经过',unknown:'待核'};
const triggers={trial_followup:'课后接续',trial_preparation:'试听准备',course_verify:'课况待核',customer_blocker:'客户卡点',commitment_due:'承诺落实',order_verify:'订单待核',scope_verify:'范围待核',service_followup:'购后服务',none:'常规'};
const attentionNames={manager:'主管过问',advisor:'顾问跟进',historical:'历史带教',none:'暂不置顶'};
function header(title,select=false){const T=D.target_period,W=D.reporting_window;return `<header><div><h1>${h(title)}</h1><div class="muted">${T?'考核周 '+h(T.start.slice(0,10))+' — '+h(T.end.slice(0,10)):'统计 '+h(W.week_start.slice(0,10))+' — '+h(W.week_end.slice(0,10))}${T?'<br>已观察至 '+h(W.week_end):''}</div></div><div class="toolbar">${select?`<select id="scope" aria-label="查看团队或顾问"><option value="all">全部团队</option>${D.source_members.map(m=>`<option value="${h(m.sales_id)}" ${scope===m.sales_id?'selected':''}>${h(m.sales_name)}</option>`).join('')}</select>`:''}<span class="tag">AI 初判 · 原话可核查</span></div></header>`}
function footer(){return `<footer>资料截止 ${h(D.reporting_window.cutoff)} · ${h(D.reporting_window.time_basis)} · 仅代表该快照，不表示当前客户状态</footer>`}
function paceNote(value,label){const P=value?.pace;if(!P)return `<div class="muted">${h(label)}进度基准待接</div>`;const names={behind:'低于截至目标',on_track:'达到截至目标',ahead:'高于截至目标'};return `<div class="muted">${h(label)}：${h(names[P.status]||'进度待核')} · 应达 ${money(P.expected_net_revenue)} · 实际 ${money(P.actual_net_revenue)} · 差额 ${money(P.gap)}<br>截至 ${h(P.as_of)}<details><summary>进度依据</summary>${h(P.source)}</details></div>`}
function metrics(){const B=D.business,s=B.available?(scope==='all'?B.team:B.advisors.find(a=>a.sales_id===scope)):null,M=scope==='all'?B.monthly:null;return `<div class="metrics"><div class="metric"><span>${scope==='all'?'本月累计净营收':'个人本月累计净营收'}${M?' · '+h(M.business_month):''}</span><strong>${M?money(M.net_revenue):scope==='all'?'月累计待接':'个人月累计待接'}</strong><small>月目标 ${money(M?.target)} · 完成 ${pct(M?.target_attainment)}</small><div class="track"><div class="fill" style="width:${Math.max(0,Math.min(100,(M?.target_attainment||0)*100))}%"></div></div>${paceNote(M,'月度')}<small>本周净营收 ${money(s?.net_revenue)} · 周目标 ${money(s?.target)}</small>${paceNote(s,'本周')}</div><div class="metric"><span>本周有效流量转化率</span><strong>${pct(s?.effective_conversion_rate)}</strong><small>首次正式购买 ${num(s?.first_formal_purchases)} / 有效承接 ${num(s?.effective_leads)} · 目标 ${pct(B.targets?.effective_conversion)}</small></div><div class="metric"><span>本周首次正课客单价</span><strong>${s?.average_order_status==='no_first_formal_purchases'?'—':money(s?.first_formal_order_average_rmb)}</strong><small>${averageNote(s)} · 目标 ${money(B.targets?.first_formal_order_rmb)}</small></div></div>`}
function contactNote(r){const c=r.contact_status||r.source?.contact_status;if(!c||!['temporary_unreachable','waiting','wait_unknown','reengaged','policy_unknown'].includes(c.status))return '';const retained=r.contact_refresh_status==='retained_unverified',routing=r.contact_routing;return `<div class="note"><b>${h(c.label||'联系状态')}</b>${retained?' · 上次标记，本期待复核':''}<br>${h(c.why||'')}${c.review_note?'<br>'+h(c.review_note):''}${routing?.reason?'<br>'+h(routing.reason):''}<div class="muted">联系判定截至 ${h(c.as_of||'待核')}</div></div>`}
function chip(r){return `<button class="chip" data-case="${rowIndex(r)}">${h(r.name)} ↗</button>`}
function card(r){const q=r.source.trial_warning||{},prior=(D.opportunity_pool?.entries||[]).some(e=>e.is_prior&&e.refresh_status==='current'&&e.sales_id===r.sales_id&&e.case_id===r.case_id);return `<article class="card"><div><span class="tag ${h(['red','orange','yellow'].includes(q.code)?q.code:'')}">${h(triggers[r.decision.trigger])}</span><span class="person">　${h(r.sales_name)} · ${h(r.name)}${prior?' · 往期商机':''}</span></div><h3>${h(r.decision.title)}</h3>${contactNote(r)}<div class="question"><span class="muted">主管先问</span><br>${h(r.manager_question)}</div><button class="link" data-case="${rowIndex(r)}">查看依据与下一步 →</button></article>`}
const poolFor=id=>(D.opportunity_pool?.entries||[]).find(e=>e.pool_id===id),historyRows=key=>filtered((D.history_followup?.[key]||[]).map(poolFor).filter(Boolean)),opportunityNames={open:'推进中',waiting:'等待中',dormant:'暂缓，尚未结束',unknown:'状态待核',won:'已正式购买',closed:'需求已结束',none:'本次无销售需求'};
function historyCard(e){const s=e.snapshot,current=e.refresh_status==='current';return `<article class="card"><div class="person">${h(e.sales_name)} · ${h(e.name)}</div><span class="tag">${current?'本期已有复核':'本期未复核'}</span><h3>${h(current?s.decision?.title||opportunityNames[e.status]:'上次：'+opportunityNames[e.status])}</h3>${contactNote(e)}<div class="muted">上次资料截止 ${h(e.last_observed_cutoff)}${e.state_note?'<br>'+h(e.state_note):''}</div><button class="link" data-pool="${h(e.pool_id)}">${current?'查看当前依据':'查看上次判断与待核事项'} →</button></article>`}
function pausedItems(){const out=[],seen=new Set(),current=new Set();for(const e of D.opportunity_pool?.entries||[]){if(!e.is_open||!e.contact_routing?.paused)continue;if(seen.has(e.pool_id))continue;seen.add(e.pool_id);out.push({entry:e});if(e.refresh_status==='current')current.add(JSON.stringify([e.sales_id,e.case_id]));}for(const r of D.paused_contact||[]){const key=JSON.stringify([r.sales_id,r.case_id]);if(current.has(key))continue;current.add(key);out.push({row:r});}return out.filter(x=>scope==='all'||(x.entry||x.row).sales_id===scope)}
function pausedCard(item){return item.entry?historyCard(item.entry):card(item.row)}
function historySection(){const P=D.opportunity_pool,now=historyRows('current'),stale=historyRows('unrefreshed'),paused=pausedItems(),show=[...now,...stale].slice(0,D.homepage_limit);return `<section class="section"><div class="section-head"><h2>往期商机跟进</h2><button class="link" data-modal="history">查看保留清单 →</button></div>${!P||P.baseline_only?'<div class="note">已建立本期管理基线；未提供往期交付，往期商机数量待核。</div>':`<div class="muted">本期需跟进 ${now.length} 项 · 旧重点待复核 ${stale.length} 项 · 与今日关注可能是同一需求，不重复计数。</div>`}<div class="grid" style="margin-top:16px">${show.map(historyCard).join('')||(!P?.baseline_only?'<div class="empty">本次已接入历史中，暂无需优先展示的往期事项；等待、身份待核及已结束记录可展开。</div>':'')}</div>${paused.length?`<details style="margin-top:18px"><summary>暂时失联 · ${paused.length} 项（普通追单暂停，可恢复）</summary><div class="muted">包括本期与往期记录；身份待核可同时出现，不代表新增客户。</div><div class="grid" style="margin-top:16px">${paused.slice(0,D.homepage_limit).map(pausedCard).join('')}</div><button class="link" data-modal="history">查看全部保留项 →</button></details>`:''}</section>`}
function overview(){let q=filtered(D.queue),focuses=filtered(D.advisor_focus);main.innerHTML=header('经营总览',true)+metrics()+`<section class="section"><div class="section-head"><h2>今日关注</h2><button class="link" data-modal="attention">${q.length} 个值得过问的客户 →</button></div><div class="grid">${q.slice(0,D.homepage_limit).map(card).join('')||'<div class="empty">本快照没有已举证的主管优先事项。</div>'}</div></section>`+historySection()+`<section class="section"><div class="section-head"><h2>带教提示</h2><button class="link" data-page="coaching">顾问带教 →</button></div><div class="hints">${focuses.map(f=>`<div class="hint"><b>${h(f.sales_name)}</b><span>${h(f.plan?.skill||'暂无有依据的个性训练重点')}</span><button class="link" data-focus="${D.advisor_focus.indexOf(f)}">展开 →</button></div>`).join('')}</div></section>`+footer();bind()}
function chart(kind){const B=D.business,rows=B.advisors||[],title={revenue:'净营收与周目标',conversion:'有效流量转化率',average:'首次正课客单价'}[kind];return `<div class="chart"><h3>${title}</h3>${rows.length?rows.map(a=>{const name=D.source_members.find(m=>m.sales_id===a.sales_id)?.sales_name||a.sales_id;let value,goal,label;if(kind==='revenue'){value=a.net_revenue;goal=a.target;label=money(value)}else if(kind==='conversion'){value=a.effective_conversion_rate;goal=B.targets.effective_conversion;label=pct(value)}else{value=a.first_formal_order_average_rmb;goal=B.targets.first_formal_order_rmb;label=a.average_order_status==='no_first_formal_purchases'?'—':money(value)}let width=value==null||!goal?0:Math.max(0,Math.min(100,value/goal*100));return `<div class="bar-row"><div class="bar-label"><b>${h(name)}</b><span>${label}</span></div><div class="track"><div class="fill" style="width:${width}%"></div></div><div class="muted">${value==null?(kind==='average'?averageNote(a):'数据待补')+' · ':''}目标 ${kind==='conversion'?pct(goal):money(goal)}</div>${kind==='revenue'?paceNote(a,'本周'):''}</div>`}).join(''):'<div class="missing">业务数据尚未接入</div>'}</div>`}
function coaching(){main.innerHTML=header('顾问带教')+`<div class="grid">${chart('revenue')}${chart('conversion')}${chart('average')}</div><section class="section"><div class="section-head"><h2>本周带教重点</h2><span class="muted">团队共性 · 不作因果归责</span></div>${D.team_topics.map((t,i)=>`<article class="topic"><div><h3>${h(t.title)}</h3><div class="muted">${t.counts.gap_advisor_count} 位顾问 · ${t.counts.gap_case_count} 个缺口案例</div><div class="chips">${t.members.slice(0,3).map(m=>chip(rowFor(m.sales_id,m.case_id))).join('')}<button class="chip" data-topic="${i}">查看全部依据 →</button></div></div><div class="practice"><span class="muted">统一训练</span><p>${h(t.exercise)}</p></div></article>`).join('')||'<div class="empty">暂无满足证据要求的团队共同训练主题。</div>'}</section><section class="section"><div class="section-head"><h2>各顾问带教</h2></div><div class="grid">${D.advisor_focus.map((f,i)=>`<article class="card"><div class="person">${h(f.sales_name)}</div><h3>${h(f.plan?.skill||'暂无单独训练重点')}</h3><div class="muted">${h(f.reason)}</div><div class="chips">${f.case_ids.slice(0,2).map(cid=>chip(rowFor(f.sales_id,cid))).join('')}</div><button class="link" data-focus="${i}">查看训练与通过标准 →</button></article>`).join('')}</div></section>`+footer();bind()}
function detailField(label,value){return value==null||value===''?'':`<dt>${h(label)}</dt><dd>${h(value)}</dd>`}
function quoteRefs(r,refs){const ids=new Set(refs||[]),messages=(r.source.evidence||[]).filter(m=>ids.has(m.id));return messages.length?`<details><summary>查看对应原话 · ${messages.length} 条</summary>${messages.map(m=>`<article class="message"><div class="meta">${h(m.time)} · ${h(m.speaker||m.source_role)} · ${h(m.id)}</div>${h(m.text)}</article>`).join('')}</details>`:''}
function warningDetail(r){const t=r.source.trial||{},q=r.source.trial_warning;if(!q||(!t.paid&&!t.completed&&['not_completed','not_applicable','inactive'].includes(q.code)))return '';return `<details class="detail-block"><summary>试听接续 · ${h(q.label||'状态待核')}</summary><dl>${detailField('完课后经过',q.elapsed||(q.hours==null?'计时待核':q.hours+' 小时'))}${detailField('计时截至',D.reporting_window.cutoff)}${detailField('完课记录',t.completion_note)}${detailField('时间依据',t.time_note)}${detailField('完课时间范围',t.ended_from||t.ended_to?String(t.ended_from||'起点待核')+' — '+String(t.ended_to||'终点待核'):null)}</dl>${quoteRefs(r,t.completion_refs)}</details>`}
function diagnosisDetail(r){const L=r.source.layers||{},R=r.source.recovery||{},layerNames={judgment:'第一层 · 销售判断',expression:'第二层 · 客户表达',execution:'执行兑现'},statusNames={gap:'可见缺口',sound:'未见该缺口',unknown:'待核',not_applicable:'不适用'},nodes=L.diagnostic_nodes||[],library=L.library||[],training=L.training;let sections='';
const layers=Object.entries(layerNames).filter(([key])=>L[key]);if(layers.length)sections+=`<details class="detail-block"><summary>判断、表达与执行依据</summary>${layers.map(([key,label])=>{const v=L[key];return `<section><h3>${h(label)} · ${h(statusNames[v.status]||v.status)}</h3><dl>${detailField('观察到什么',v.finding)}${detailField('应完成什么',v.expected)}</dl>${quoteRefs(r,v.refs)}</section>`}).join('')}</details>`;
if(nodes.length)sections+=`<details class="detail-block"><summary>逐节点复盘 · ${nodes.length} 处</summary>${nodes.map(n=>`<details><summary>${h(names[n.stage]||n.stage)} · ${h(n.gap)}</summary><dl>${detailField('当时客户要决定',n.customer_decision)}${detailField('销售当时动作',n.sales_action)}${detailField('记录范围',n.sales_action_evidence==='not_observed'?n.coverage_limit:null)}${detailField('可能影响（分析推断）',n.possible_effect)}${detailField('当时更合适的动作',n.better_action)}${detailField(r.contact_routing?.paused?'原跟进建议（待恢复后重评）':'现在如何跟进',n.current_action)}${detailField('判断限度',n.limit)}${detailField('对应培训依据',library[n.library_index]?.locator)}</dl>${quoteRefs(r,[...(n.customer_refs||[]),...(n.sales_refs||[]),...(n.later_feedback_refs||[])])}</details>`).join('')}</details>`;
if(training)sections+=`<details class="detail-block"><summary>本案训练与通过标准</summary><dl>${detailField('训练动作',training.action)}${detailField('怎样练',training.exercise)}${detailField('怎样算通过',training.pass_criteria)}${detailField('训练状态',training.status==='proposed'?'建议，尚未证明已执行':training.status)}</dl></details>`;
if(library.length)sections+=`<details class="detail-block"><summary>对应话术库与培训依据 · ${library.length} 处</summary>${library.map(l=>`<section><h3>${h(l.locator||'来源依据')}</h3><p>${h(l.quote)}</p><div class="muted">${h(l.path)}</div><dl>${detailField('本案怎样使用',l.rationale)}${detailField('应用情况',({not_used:'未体现适用方法',partial:'只体现了部分',misapplied:'时机或条件不适用',appropriate:'已恰当体现',unknown:'不足以判断使用情况',not_applicable:'本案不适用'})[l.application]||l.application)}</dl>${quoteRefs(r,l.refs)}</section>`).join('')}</details>`;
if(R.script||R.script_conditions||R.next_signal)sections+=`<details class="detail-block"><summary>${r.contact_routing?.paused?'原建议话术与推进信号（历史参考）':'建议话术与推进信号'}</summary>${r.contact_routing?.paused?'<p class="note">普通追单已暂停。以下保留原分析供带教，不能据此继续催发；恢复后先按新情况复核。</p>':''}<dl>${detailField('客户参考话术',R.script)}${detailField('适用条件',R.script_conditions)}${detailField('下一推进信号',R.next_signal)}</dl></details>`;return sections}
function detail(index){const r=D.cases[index];if(!r)return;if(page!=='detail')lastPage=page;page='detail';close();main.innerHTML=`<button class="link" data-back>← 返回</button>`+header(r.name+' · '+r.sales_name)+`<div class="detail-grid"><section class="evidence"><h3>标准结果引用的原话</h3><div class="muted">此处为被引用证据，不是完整聊天。${h(r.case_id)}</div>${(r.source.evidence||[]).map(m=>`<article class="message"><div class="meta">${h(m.time)} · ${h(m.speaker||m.source_role)} · ${h(m.id)}<br>${h(m.sheet)} / 行 ${h(m.row)}</div>${h(m.text)}</article>`).join('')||'<div class="empty">暂无可展示的引用原话。</div>'}</section><div><section class="detail-block"><span class="tag">${h(attentionNames[r.decision.attention])}</span><h3>${h(r.decision.title)}</h3><p>${h(r.decision.why)}</p>${contactNote(r)}<div class="phases">${Object.entries(r.source.current_phases||{}).map(([k,v])=>`<span class="tag">${h(names[k]||k)} · ${h(states[v.state]||v.state)}</span>`).join('')}</div></section><section class="detail-block"><h3>主管先问</h3><p>${h(r.manager_question)}</p><dt>${r.contact_routing?.paused?'原建议（普通追单已暂停）':'下一步'}</dt>${r.contact_routing?.paused?'<p>当前暂停普通追单；客户恢复回复后，先按新情况复核原建议。</p>':''}<p>${h(r.action?.action||'本次未另选行动，源建议保留供核查。')}</p>${r.action?`<div class="muted">${h(r.action.owner)} · ${h(r.action.when)}</div>`:''}</section>${r.decision.trial_preparation?`<section class="detail-block"><h3>试听准备检查</h3><dl><dt>学生目标</dt><dd>${h(r.decision.trial_preparation.student_goal)}</dd><dt>教师确认</dt><dd>${h(r.decision.trial_preparation.teacher_alignment)}</dd><dt>具体准备</dt><dd>${h(r.decision.trial_preparation.preparation)}</dd></dl></section>`:''}${warningDetail(r)}${diagnosisDetail(r)}<section class="detail-block"><h3>判断边界</h3><p>${h(r.source.layers?.causal_limit||'以标准结果的可见证据为限。')}</p><div class="note">${h(r.source.recovery?.reason||'')}</div></section></div></div>`+footer();bind();window.scrollTo(0,0)}
function table(rows,decision=false){return `<div class="table-wrap"><table><thead><tr><th>顾问 / 客户</th><th>${decision?'分流决定':'当前提示'}</th><th>理由</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="nowrap">${h(r.sales_name)}<br>${h(r.name)}</td><td>${h(decision?attentionNames[r.decision.attention]:r.decision.title)}${r.contact_routing?.paused?'<br><span class="tag">暂时失联 · 暂停普通追单</span>':''}</td><td>${h(r.decision.why)}${r.contact_routing?.paused||r.contact_routing?.protected?'<br>'+h(r.contact_routing.reason):''}</td><td><button class="link" data-case="${rowIndex(r)}">查看</button></td></tr>`).join('')}</tbody></table></div>`}
function modal(title,body){modalRoot.innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${h(title)}"><div class="modal-head"><h2>${h(title)}</h2><button class="close" aria-label="关闭" data-close>×</button></div>${body}</section></div>`;bind(modalRoot);modalRoot.querySelector('[data-close]').focus()}
function close(){modalRoot.innerHTML=''}
function showHistory(){const labels={current:'本期复核后需要跟进',unrefreshed:'旧重点 · 本期未复核',waiting:'等待及其他保留事项',temporary_unreachable:'暂时失联（含本期，可恢复）',identity_pending:'身份或归属待核',closed_this_run:'本次已有结束依据'};modal('往期商机跟进',`<p class="muted">只展示已提供历史中的需求。首次纳入周是管理基线，不是客户添加日；未复核不会被当作新结论或自动流失。联系状态与身份待核可以同时出现，同一记录不重复算新增客户。</p>`+Object.entries(labels).map(([k,label])=>{const paused=k==='temporary_unreachable',rows=paused?pausedItems():historyRows(k);return `<details ${k==='current'||k==='unrefreshed'?'open':''}><summary>${label} · ${rows.length} 项</summary><div class="grid" style="margin:16px 0">${rows.map(paused?pausedCard:historyCard).join('')||'<div class="muted">本次没有此类记录。</div>'}</div></details>`}).join(''))}
function poolDetail(id){const e=poolFor(id);if(!e)return;const s=e.snapshot,live=rowFor(e.sales_id,e.case_id);if(e.refresh_status==='current'&&live){detail(rowIndex(live));return}modal(e.name+' · 上次商机快照',`<p><b>${h(opportunityNames[e.status])}</b> · 本期未复核</p><p>${h(e.state_note)}</p>${contactNote(e)}<p class="muted">首次纳入管理周 ${h(e.first_tracked_week)}；上次资料截止 ${h(e.last_observed_cutoff)}<br>来源 ${h(e.last_source.analysis_id)} / ${h(e.last_source.case_id)}</p><h3>上次判断</h3><p>${h(s.decision?.title||s.source?.headline)}</p><p>${h(s.decision?.why||s.source?.recovery?.reason)}</p><h3>上次建议，执行情况待核</h3><p>${h(s.action?.action||s.source?.recovery?.actions?.[0]?.action||'未登记可用动作')}</p><h3>上次引用依据</h3>${(s.source?.evidence||[]).map(m=>`<article class="message"><div class="meta">${h(m.time)} · ${h(m.id)}</div>${h(m.text)}</article>`).join('')}`)}
function showModal(which){if(which==='attention'){modal('全部主管关注',table(filtered(D.queue)));return}if(which==='cases'){modal('全部案例',table(filtered(D.cases)));return}if(which==='decisions'){modal('完整决策记录',`<p class="muted">全部 ${D.decision_log.length} 个纳入案例均有去向。未进主管队列不删除源跟进事项。</p>`+table(D.cases,true)+`<h3 style="margin-top:28px">源标准报告必须跟回 · ${D.source_must_follow.length} 项</h3>`+table(D.source_must_follow.map(m=>rowFor(m.sales_id,m.case_id))));return}modal('数据与口径',`<p>统计期 ${h(D.reporting_window.week_start)} — ${h(D.reporting_window.week_end)}；建议资料截止 ${h(D.reporting_window.cutoff)}。</p><p>${h(D.reporting_window.time_basis)}</p>${D.business.reporting_window?.cutoff?`<p>业务数据截止 ${h(D.business.reporting_window.cutoff)}</p>`:''}${D.business.business_month?`<p>经营月 ${h(D.business.business_month)}（按业务系统指定整周归属）</p>`:''}<p>源Skill版本 ${h(D.source_skill_version)}；主管模块运行版本 ${h(D.runtime.skill_version)}。源结果已独立核验；模型调用覆盖未核验，未登记主管批准。</p><p>${h(D.business.scope_note||'尚未接入经营数据；不会用聊天金额或旧均单代替首次正课客单价。')}</p><div class="note">${h(D.limitations.join('\n'))}</div><h3 style="margin-top:24px">成员来源</h3>${D.source_members.map(m=>`<p><b>${h(m.sales_name)}</b><br><small>${h(m.analysis_id)}</small></p>`).join('')}<h3>业务定义</h3><pre>${h(JSON.stringify(D.business.definitions||{},null,2))}</pre><p class="muted">团队分析编号：${h(D.team_analysis_id)}</p>`)}
function focus(i){const f=D.advisor_focus[i];modal(f.sales_name+' · 带教重点',f.plan?`<h3>${h(f.plan.skill)}</h3><p>${h(f.reason)}</p><h3>练习</h3><p>${h(f.plan.exercise)}</p><h3>怎样算完成</h3><p>${h(f.plan.pass_criteria)}</p><div class="chips">${f.case_ids.map(cid=>chip(rowFor(f.sales_id,cid))).join('')}</div><p class="muted">状态：建议，尚未证明培训已执行。</p>`:`<p>${h(f.reason)}</p>`)}
function topic(i){const t=D.team_topics[i];modal(t.title,`<p>${h(t.opportunity_definition)}</p><div class="note">${h(t.count_note)}</div>${t.members.map(m=>{const r=rowFor(m.sales_id,m.case_id);return `<p><b>${h(r.sales_name)} · ${h(r.name)}</b>　${h(m.status==='gap'?'可见缺口':m.status==='sound'?'未见此缺口':'待核')}<br>${h(m.why_same)}<br>${chip(r)}</p>`}).join('')}<h3>训练依据</h3><p>${h(t.source.quote)}</p><p class="muted">${h(t.source.path)}</p><h3>通过标准</h3><p>${h(t.pass_criteria)}</p>`)}
function setPage(p){close();page=p;lastPage=p;document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));if(p==='coaching')coaching();else overview();window.scrollTo(0,0)}
function bind(root=main){root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));root.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>detail(Number(b.dataset.case)));root.querySelectorAll('[data-pool]').forEach(b=>b.onclick=()=>poolDetail(b.dataset.pool));root.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>b.dataset.modal==='history'?showHistory():showModal(b.dataset.modal));root.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);root.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>focus(Number(b.dataset.focus)));root.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>topic(Number(b.dataset.topic)));root.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>setPage(lastPage));const s=root.querySelector('#scope');if(s)s.onchange=()=>{scope=s.value;overview()}}
document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});bind(document.querySelector('.sidebar'));overview();
</script></body></html>'''
    return template.replace('__AID__', aid).replace('__PAYLOAD__', payload)
